def consume(queue, qty):
    used = min(qty, sum(n for n, p in queue))
    remaining, cost = used, 0
    while remaining:
        n, p = queue[0]
        take = min(n, remaining)
        cost += take * p
        remaining -= take
        if take == n:
            queue.pop(0)
        else:
            queue[0] = (n - take, p)
    return used, cost

