from settings import THRESHOLD
from order import ordered
from window import trim
from resetter import reset
def solve(events):
    history, seen, alerts = {}, set(), []
    for idx,e in ordered(events):
        if e['id'] in seen:
            continue
        seen.add(e['id'])
        k = (e['user'],e['ip'])
        if e['outcome'] == 'success':
            reset(history,k)
        else:
            prior = trim(history.get(k,[]),e['time'])
            history[k] = prior + [e['time']]
            if len(prior) < THRESHOLD <= len(prior)+1:
                alerts.append([e['user'],e['ip'],e['time']])
    return alerts

