def shortest(graph,source):
    n=len(graph)
    distance=[None]*n
    parent=[None]*n
    distance[source]=0
    for turn in range(n-1):
        changed=False
        for a in range(n):
            if distance[a] is not None:
                for idx,e in enumerate(graph[a]):
                    b,rev,cap,cost=e
                    if cap>0 and (distance[b] is None or distance[a]+cost<distance[b]):
                        distance[b]=distance[a]+cost
                        parent[b]=(a,idx)
                        changed=True
        if not changed:
            break
    return distance,parent

