from network import edge
from paths import shortest
from augment import send
def solve(workers,jobs,quotes):
    wmap={name:i+1 for i,(name,c) in enumerate(workers)}
    jmap={name:len(workers)+i+1 for i,(name,d) in enumerate(jobs)}
    source,sink=0,len(workers)+len(jobs)+1
    graph=[[] for i in range(sink+1)]
    for name,c in workers:
        edge(graph,source,wmap[name],c,0)
    for name,d in jobs:
        edge(graph,jmap[name],sink,d,0)
    for w,j,c in quotes:
        edge(graph,wmap[w],jmap[j],sum(d for name,d in jobs),c)
    filled,total=0,0
    while True:
        distance,parent=shortest(graph,source)
        if distance[sink] is None:
            break
        amount=send(graph,parent,source,sink)
        filled+=amount
        total+=amount*distance[sink]
    return {'filled':filled,'cost':total}

